queries.item:
CREATE TABLE IF NOT EXISTS `?:ab__emd_patterns` (
`pattern_id` mediumint(8) unsigned NOT NULL auto_increment,
`company_id` int(11) unsigned NOT NULL default 0,
`object` varchar(255) NOT NULL default '',
PRIMARY KEY (`pattern_id`)
) DEFAULT CHARSET=utf8;

CREATE TABLE IF NOT EXISTS `?:ab__emd_categories_patterns` (
`category_id` mediumint(8) unsigned NOT NULL,
`category_pattern_id` mediumint(8) unsigned NOT NULL,
`products_pattern_id` mediumint(8) unsigned NOT NULL,
PRIMARY KEY (`category_id`)
) DEFAULT CHARSET=utf8;
